import{_ as n}from"./chunks/entity-picker.BuWRM8I6.js";import{_ as t,o as i,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Home-Assistant-Entitäten","description":"Entitäten aus HA laden, suchen und in Blocks übernehmen.","frontmatter":{"title":"Home-Assistant-Entitäten","description":"Entitäten aus HA laden, suchen und in Blocks übernehmen."},"headers":[],"relativePath":"projects/blocks-for-ha/entities.md","filePath":"projects/blocks-for-ha/entities.md","lastUpdated":1792840662000}'),s={name:"projects/blocks-for-ha/entities.md"};function d(l,e,o,h,u,c){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="entitaten-auswahlen" tabindex="-1">Entitäten auswählen <a class="header-anchor" href="#entitaten-auswahlen" aria-label="Permalink to &quot;Entitäten auswählen&quot;">​</a></h1><p>Seit <strong>0.1.44</strong> öffnen passende Aktions- und Zielfelder der einfachen und erweiterten Blocks eine durchsuchbare Auswahl. Ein kleiner Pfeil markiert diese Felder. <strong>HA-Auswahl laden</strong> in der Werkzeugleiste und <strong>Neu laden</strong> im Dialog aktualisieren die lesenden Kataloge.</p><p><img src="'+n+'" alt="Entitätsauswahl mit Suchergebnis"></p><p>Das Bild verwendet simulierte Testentitäten und die deutsche Oberfläche. Seit 0.1.46 folgt die Oberfläche der gewählten App-Sprache DE/EN/FR. Entitätsnamen kommen unverändert aus deiner HA-Installation.</p><h2 id="bedienung" tabindex="-1">Bedienung <a class="header-anchor" href="#bedienung" aria-label="Permalink to &quot;Bedienung&quot;">​</a></h2><ol><li>Auf die Entitäts-ID im Block klicken.</li><li>Nach Name oder ID suchen. Mehrere Suchwörter müssen alle passen. Die ersten 150 Treffer werden angezeigt; bei großen Listen die Suche eingrenzen.</li><li>Ein Ergebnis auswählen und <strong>Übernehmen</strong> drücken. Erst dann wird der Block geändert. <strong>Abbrechen</strong> oder Escape lässt ihn unverändert.</li><li>Alternativ eine ID wie <code>light.wohnzimmer</code> direkt eingeben. Das funktioniert auch ohne Verbindung oder für nicht geladene Entitäten.</li></ol><p>Die Liste zeigt Name, ID und aktuellen Zustand mit Einheit. Diese Zustände sind eine <strong>Momentaufnahme</strong>, keine laufende Überwachung und keine Sensor-Wertblocks für die Automation.</p><table tabindex="0"><thead><tr><th>Block</th><th>Auswahl</th></tr></thead><tbody><tr><td>Zustand-/Zahlenauslöser und Bedingungen</td><td>Alle geladenen Entitäten</td></tr><tr><td>Licht mit Farbe/Helligkeit</td><td>Nur <code>light</code></td></tr><tr><td>HA-Script</td><td>Nur <code>script</code></td></tr><tr><td>Helfer</td><td>Aktuell gewählter Typ: <code>input_boolean</code>, <code>counter</code> oder <code>timer</code></td></tr><tr><td>Ein/Aus/Umschalten, Entität aktualisieren, generische HA-Aktion</td><td>Alle geladenen Entitäten; Unterstützung der Aktion weiterhin in HA prüfen</td></tr></tbody></table><p>Aktionsfelder zeigen die von HA gemeldeten Aktionen. Entitätsziele berücksichtigen die Domains der Aktionsbeschreibung oder des Aktionsnamens. Die Zielauswahl folgt <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> oder <code>label_id</code>: Entitäten, Geräte, Bereiche, Etagen oder Labels. Die letzten vier Kataloge werden nicht anhand der Aktion gefiltert. <strong>Mehrere Ziele auswählen</strong> erlaubt Listen in unterstützten Feldern. Freie IDs, JSON-Listen und unterstützte Jinja-Templates bleiben möglich; mehrzeiliger Jinja-Text wird vollständig erhalten. Ein Zielartwechsel schreibt vorhandene IDs nicht um.</p><p>Szenen und Helfer bieten passende Entitätsdomains; erweiterte numerische Grenzen zusätzlich Sensoren und Zahlenhelfer, Zeitfelder Zeithelfer und Sensoren. Manuelle Zahlen/Uhrzeiten bleiben möglich. Fachliche Dropdowns bleiben erhalten. Variablennamen, Trigger-IDs, Attribute, freier Text und komplexe Daten erhalten keine pauschale HA-Auswahl. Ein ID-Wechsel ersetzt keine Referenzen in frei eingegebenen Jinja- oder JSON-Daten. Ohne Aktionskatalog erscheinen ausdrücklich gekennzeichnete gängige Beispiele; fehlende Zielkataloge erlauben manuelle IDs.</p><h2 id="ha-app-und-daten" tabindex="-1">HA-App und Daten <a class="header-anchor" href="#ha-app-und-daten" aria-label="Permalink to &quot;HA-App und Daten&quot;">​</a></h2><p>Repository im HA-App-Store aktualisieren, <strong>Version 0.1.44</strong> installieren und die App neu starten. Die App benötigt <code>homeassistant_api: true</code> und verwendet den serverseitigen <code>SUPERVISOR_TOKEN</code>. Entitäten und Aktionen werden über die <a href="https://developers.home-assistant.io/docs/api/rest/" target="_blank" rel="noreferrer">REST-API</a> gelesen, Zielregistrierungen über die <a href="https://developers.home-assistant.io/docs/api/websocket/" target="_blank" rel="noreferrer">WebSocket-API</a>. Fehlende Registry-Berechtigungen betreffen nur die jeweilige Liste. Im Editor ist keine Token-Eingabe nötig.</p><p>Der Browser erhält nur Auswahlmetadaten: ID, Anzeigename, Domains und bei Entitäten Zustand/Einheit. Weitere Attribute und Zugangsdaten werden nicht weitergegeben. Die Endpunkte lesen ausschließlich Kataloge und führen keine HA-Aktionen aus. Der Server folgt keinen Weiterleitungen mit Zugangsdaten.</p><p>Die Liste stammt aus der HA-Zustandsliste, nicht aus der gesamten Entitätsregistrierung. Deaktivierte oder noch nicht verfügbare Entitäten ohne Zustand können fehlen. <code>unknown</code>/<code>unavailable</code> werden angezeigt, wenn sie in der Liste vorhanden sind. Bei einem Ladefehler wird die bisherige Liste verworfen; bestehende Block-IDs bleiben erhalten.</p><p>Im JSON-Projekt und im YAML stehen die gewählten Feldwerte. Katalog, Namen, Zustandsvorschau und Zugangsdaten werden nicht gespeichert oder exportiert. Alle 163 Blocktypen bleiben erhalten. Vor einem Update das eigene Browserprojekt über <strong>Projekt sichern</strong> herunterladen; ein Quellcode-Backup enthält keine Browsersitzung.</p><h2 id="lokale-entwicklung" tabindex="-1">Lokale Entwicklung <a class="header-anchor" href="#lokale-entwicklung" aria-label="Permalink to &quot;Lokale Entwicklung&quot;">​</a></h2><p>Die Python-Abhängigkeit einmal mit <code>python -m pip install --require-hashes -r requirements.txt</code> installieren. Docker installiert sie automatisch.</p><p><code>npm run dev</code> allein arbeitet mit manuellen IDs. Für eine Verbindung zusätzlich Python 3 starten: <code>npm run entities</code>. Nur im Serverprozess die Umgebungsvariablen <code>BLOCKS_HA_URL</code> (Basisadresse ohne <code>/api</code>, etwa <code>http://homeassistant.local:8123</code>) und <code>BLOCKS_HA_TOKEN</code> setzen. Der Vite-Server auf <code>127.0.0.1:4180</code> leitet die Abfrage an die lokale Bridge auf <code>127.0.0.1:9001</code> weiter. Keine Zugangsdaten in Quellcode oder Projektdateien eintragen.</p><p>Die Docker-Version startet Bridge und Weboberfläche gemeinsam. Außerhalb von HA mit gesetzten Zugangsdaten nur lokal binden oder eine authentifizierte vorgeschaltete Oberfläche verwenden; eigenständige Benutzeranmeldung ist noch nicht enthalten. In HA schützt Ingress den Zugriff.</p><h2 id="prufung" tabindex="-1">Prüfung <a class="header-anchor" href="#prufung" aria-label="Permalink to &quot;Prüfung&quot;">​</a></h2><p>Geprüft sind Projekt-/YAML-Kompatibilität, Suche, Filter, Abbrechen, manuelle Eingabe, Fehlerfälle, mobiles Layout und die vollständige Docker-Kette gegen einen simulierten HA-Server. Ein praktischer Test in einer echten HA-Installation steht noch aus. Die Entitätsauswahl bestätigt nicht, dass eine konkrete Aktion vom gewählten Gerät unterstützt wird.</p>',21)])])}const b=t(s,[["render",d]]);export{m as __pageData,b as default};
